INSERT INTO lessons (level_id,lesson_key,sort_order,title,title_translation,description,primary_outcome_key,estimated_duration_sec,source_hash,status,metadata)
VALUES (@level_id,'EN-A1-L-0001',1,'Hello! What''s your name?','سلام! اسمت چیه؟','برای شروع کلاس آمده ای و با همکلاسی تازه ات مایا آشنا می شوی.','A1-INTERACTION-GREET-NAME',420,'bd1ff62238d1d95fd5408897ab389a84f1c783565738e10bdee7a0192dd6f51a','validated','{"outcomeFa":"زبان آموز می تواند سلام کند، خودش را کوتاه معرفی کند و اسم طرف مقابل را بپرسد.","scenarioFa":"برای شروع کلاس آمده ای و با همکلاسی تازه ات مایا آشنا می شوی. نقش تو الکس است.","prerequisiteOutcomeKeys":[],"curriculum":{"startingKnowledge":"absolute_zero","targetConstructions":[{"key":"EN-CONSTR-IM-NAME","form":"I''m + name","meaningFa":"برای معرفی کوتاه اسم"},{"key":"EN-CONSTR-WHATS-YOUR-NAME","form":"What''s your name?","meaningFa":"برای پرسیدن اسم طرف مقابل"}],"supportLanguage":[],"assessmentBoundary":"Guided speech and audio reconstruction are practice. Choice tasks assess recognition/selection. Final hidden-answer retrieval records first attempt and help separately; exact text matching cannot certify open-ended language ability or pronunciation.","transferPlan":{"mode":"same_lesson","intent":"End with meaning-cued recall without displayed English. Continue delayed review in later stories; this does not prove long-term retention."},"story":{"arcKey":"EN-A1-CLASSMATES","sceneKey":"EN-A1-SCENE-0001","learnerRoleKey":"alex","participants":["alex","maya"],"introducedCharacterKeys":["alex","maya"],"relationshipState":"first_meeting","continuesLessonKey":null,"dependsOnLessonKeys":[],"settingFa":"ورودی کلاس، اولین آشنایی","storyBeatFa":"الکس و مایا برای اولین بار خودشان را معرفی می کنند."},"reviewLinks":[],"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing"}')
ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),sort_order=VALUES(sort_order),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),primary_outcome_key=VALUES(primary_outcome_key),estimated_duration_sec=VALUES(estimated_duration_sec),source_hash=VALUES(source_hash),status=VALUES(status),metadata=VALUES(metadata);
